import PDFKit
import AppKit
let args = CommandLine.arguments
let doc = PDFDocument(url: URL(fileURLWithPath: args[1]))!
let prefix = args[2]
let only: Set<Int>? = args.count > 3 ? Set(args[3].split(separator: ",").compactMap { Int($0) }) : nil
for i in 0..<doc.pageCount {
  if let o = only, !o.contains(i+1) { continue }
  let page = doc.page(at: i)!
  let r = page.bounds(for: .mediaBox)
  let scale: CGFloat = 1400 / r.width
  let img = page.thumbnail(of: NSSize(width: r.width*scale, height: r.height*scale), for: .mediaBox)
  let rep = NSBitmapImageRep(data: img.tiffRepresentation!)!
  let data = rep.representation(using: .png, properties: [:])!
  try! data.write(to: URL(fileURLWithPath: "\(prefix)-\(i+1).png"))
}
print(doc.pageCount)
EOF
cd $S/render && swift $S/pdf2png.swift orig.pdf orig 2>&1 | tail -2; ls

